commit 5e0ccef5f3c2864dbd7a966b55ca06282fa3b2c8
Author: vasudeva8 <113358286+vasudeva8@users.noreply.github.com>
Date:   Fri Jun 9 11:43:05 2023 +0100

    Changes to avoid segfault with uncompressed bam (PR #1632)

    Avoids segfault when writing bam/bcf with mode "wbu" by
    changing "wbu" to "wb0".  The ensures the output file will
    be properly wrapped in BGZF blocks, even though it's not
    been compressed.

    Fixes #1617

diff --git a/hts.c b/hts.c
index b3f6b9a0..f2bc5fcb 100644
--- a/hts.c
+++ b/hts.c
@@ -778,151 +778,161 @@ char *hts_format_description(const htsFormat *format)
     case razf_compression:   kputs(" legacy-RAZF-compressed", &str); break;
     case xz_compression:     kputs(" XZ-compressed", &str); break;
     case zstd_compression:   kputs(" Zstandard-compressed", &str); break;
     case custom: kputs(" compressed", &str); break;
     case gzip:   kputs(" gzip-compressed", &str); break;
     case bgzf:
         switch (format->format) {
         case bam:
         case bcf:
         case csi:
         case tbi:
             // These are by definition BGZF, so just use the generic term
             kputs(" compressed", &str);
             break;
         default:
             kputs(" BGZF-compressed", &str);
             break;
         }
         break;
     default: break;
     }

     switch (format->category) {
     case sequence_data: kputs(" sequence", &str); break;
     case variant_data:  kputs(" variant calling", &str); break;
     case index_file:    kputs(" index", &str); break;
     case region_list:   kputs(" genomic region", &str); break;
     default: break;
     }

     if (format->compression == no_compression)
         switch (format->format) {
         case text_format:
         case sam:
         case crai:
         case vcf:
         case bed:
         case fai_format:
         case fqi_format:
         case fasta_format:
         case fastq_format:
         case htsget:
             kputs(" text", &str);
             break;

         case empty_format:
             break;

         default:
             kputs(" data", &str);
             break;
         }
     else
         kputs(" data", &str);

     return ks_release(&str);
 }

 htsFile *hts_open_format(const char *fn, const char *mode, const htsFormat *fmt)
 {
