         }

         if (tag_whitelist) {
             int tt = q[0]*256 + q[1];
             if (kh_get(tag, tag_whitelist, tt) == kh_end(tag_whitelist)) {
                 while (q < p && *q != '\t')
                     q++;
                 continue;
             }
