                     b->data[b->l_data++] = x;
                 } else if (x >= INT16_MIN) {
                     b->data[b->l_data++] = 's';
                     i16_to_le(x, b->data + b->l_data);
                     b->l_data += 2;
                 } else {
                     b->data[b->l_data++] = 'i';
                     i32_to_le(x, b->data + b->l_data);
                     b->l_data += 4;
                 }
             } else {
                 uint32_t x = hts_str2uint(q, &q, 32, &overflow);
                 if (x <= UINT8_MAX) {
                     b->data[b->l_data++] = 'C';
                     b->data[b->l_data++] = x;
                 } else if (x <= UINT16_MAX) {
                     b->data[b->l_data++] = 'S';
                     u16_to_le(x, b->data + b->l_data);
                     b->l_data += 2;
                 } else {
                     b->data[b->l_data++] = 'I';
                     u32_to_le(x, b->data + b->l_data);
                     b->l_data += 4;
                 }
             }
         } else if (type == 'f') {
             b->data[b->l_data++] = 'f';
             float_to_le(strtod(q, &q), b->data + b->l_data);
             b->l_data += sizeof(float);
         } else if (type == 'd') {
             b->data[b->l_data++] = 'd';
             double_to_le(strtod(q, &q), b->data + b->l_data);
