    open(out,'wb').write(d)
    n+=1
    r=subprocess.run(['/tmp/hts_open_runner',out],env={**os.environ,'ASAN_OPTIONS':'detect_leaks=0:abort_on_error=0:symbolize=1'},stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,timeout=5)
    if r.returncode not in (0,):
        err=r.stderr.decode('latin1','replace')
        if 'ERROR: AddressSanitizer' in err or 'runtime error:' in err:
            print('CRASH iter',n,'seed',name,'len',len(d),'ret',r.returncode)
            print(err[:4000])
            open('/workspace/poc_found','wb').write(d)
            sys.exit(0)
    if n%1000==0: print('iter',n, 'elapsed',time.time()-start, flush=True)
print('no crash',n)
